using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Collections.Generic;using System.Windows.Forms;using System.Threading.Tasks;using V15Voice;
public static class SubtitleUiTests {
 static int count,code;static object F(object o,string n){return o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,a);}static void Set(object o,string n,object v){o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).SetValue(o,v);}static void Check(bool ok,string n){if(!ok)throw new Exception(n);count++;Console.WriteLine("PASS "+n);}
 [STAThread]public static void Main(){Application.EnableVisualStyles();Application.ThreadException+=(s,e)=>{Console.WriteLine("UNHANDLED "+e.Exception);code=1;};var f=new MainForm();f.Shown+=async(s,e)=>{try{
  var tabs=(TabControl)F(f,"tabs");var page=(TabPage)F(f,"subtitlePage");Check(tabs.TabPages.Contains(page),"Subtitle page attached");tabs.SelectedTab=page;Application.DoEvents();Check(page.Visible,"Subtitle page selectable");Check(((ComboBox)F(f,"subtitleModel")).Items.Count==2,"Two model options");Check(((ComboBox)F(f,"subtitleDevice")).Items.Count==3,"ASR device independent from voice device");
  var fit=(ComboBox)F(f,"fitMode");fit.SelectedIndex=1;string folder=Path.Combine(Path.GetTempPath(),"asr_ui_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string txt=Path.Combine(folder,"prose.txt");File.WriteAllText(txt,"This is a sentence. Here is another sentence.");Call(f,"LoadFile",txt);Check(!fit.Enabled&&!((NumericUpDown)F(f,"maxSpeed")).Enabled,"TXT disables SRT bounds");Call(f,"LoadSample");Check(fit.Enabled&&((NumericUpDown)F(f,"maxSpeed")).Enabled&&((NumericUpDown)F(f,"minSpeed")).Enabled,"TXT to SRT sample unlocks bounds without preview");Call(f,"LoadFile",txt);string srt=Path.Combine(folder,"timed.srt");File.WriteAllText(srt,"1\n00:00:00,000 --> 00:00:03,000\nThis is a timed sentence.\n");Call(f,"LoadFile",srt);Check(fit.Enabled&&((NumericUpDown)F(f,"maxSpeed")).Enabled,"TXT to SRT import unlocks bounds");
  tabs.SelectedTab=page;Call(f,"SetBusy",true);Check(!((FlowLayoutPanel)F(f,"subtitleOptions")).Enabled&&((DataGridView)F(f,"subtitleGrid")).ReadOnly,"Editing disabled during task");Check(((Button)F(f,"globalCancel")).Enabled,"Global stop enabled");Call(f,"SetBusy",false);
  string scriptDir=Path.Combine(folder,"source","asr");Directory.CreateDirectory(scriptDir);File.WriteAllText(Path.Combine(scriptDir,"asr_worker.py"),"import sys,time,os,xml.etree.ElementTree as E\na=sys.argv\nsource=a[a.index('--input')+1]\nwith open(os.path.join(os.path.dirname(__file__),'calls'),'a') as f:f.write(source+'\\n')\nif 'bad' in source: sys.exit(5)\nif 'wait' in source: time.sleep(60)\nout=a[a.index('--output')+1]\nx=E.Element('subtitles',duration='8',device='CPU fixture',model='integration fixture',pipeline='v149-verified-1')\nE.SubElement(x,'cue',start='2',end='3.5',note='Review').text='Actual timing survives.'\nE.SubElement(x,'cue',start='5',end='6',note='').text='Second sentence.'\nE.ElementTree(x).write(out,encoding='utf-8',xml_declaration=True)\n");Set(f,"root",folder);string one=Path.Combine(folder,"one.mp4"),bad=Path.Combine(folder,"bad.mp3"),two=Path.Combine(folder,"two.mp3");foreach(string p in new[]{one,bad,two})File.WriteAllText(p,"media fixture");Call(f,"AddSubtitleFiles",new object[]{new[]{one,bad,two,one}});var jobs=(List<SubtitleJob>)F(f,"subtitleQueue");Check(jobs.Count==3,"Many files accepted and duplicates skipped");File.WriteAllText(Path.ChangeExtension(one,"srt"),"existing subtitle");await (Task)Call(f,"RunSubtitleQueue");Check(jobs.Count(j=>j.State.StartsWith("Đã xuất"))==2&&jobs.Count(j=>j.State=="Lỗi")==1,"Queue continues after failed middle file");Check(File.ReadAllText(Path.ChangeExtension(one,"srt"))=="existing subtitle"&&File.Exists(Path.Combine(folder,"one_2.srt")),"Existing SRT preserved in batch");Check(jobs[0].Document.Cues[0].Start==2&&jobs[2].Document.Cues[1].Start==5,"Actual timeline preserved in review");int calls=File.ReadAllLines(Path.Combine(scriptDir,"calls")).Length;await (Task)Call(f,"RunSubtitleQueue");Check(File.ReadAllLines(Path.Combine(scriptDir,"calls")).Length==calls+1,"Rerun skips completed files");
  var grid=(DataGridView)F(f,"subtitleJobs");grid.CurrentCell=grid.Rows[0].Cells[0];Call(f,"SelectSubtitleJob");var review=(DataGridView)F(f,"subtitleGrid");review.Rows[0].Cells[3].Value="Corrected words here.";Call(f,"SaveSubtitleEdits");Check(jobs[0].Document.Cues[0].Note.Contains("Đã sửa")&&SubtitleDocument.Load(jobs[0].Result).Cues[0].Text=="Corrected words here.","Edited text saved and flagged");
  string wait=Path.Combine(folder,"wait.mp3");File.WriteAllText(wait,"fixture");jobs.Clear();Call(f,"AddSubtitleFiles",new object[]{new[]{wait}});var task=(Task)Call(f,"RunSubtitleQueue");await Task.Delay(600);Call(f,"CancelTasks");await task;Check(jobs[0].State=="Đã dừng"&&!File.Exists(Path.ChangeExtension(wait,"srt")),"Stop cancels without partial SRT");Check(!(bool)F(f,"busy")&&((FlowLayoutPanel)F(f,"subtitleOptions")).Enabled,"Controls restored after stop");
  jobs[0].Document=new SubtitleDocument{Duration=8,Device="CPU fixture",Model="UI preview",Cues=new List<SubtitleCue>{new SubtitleCue{Start=2,End=3.5,Text="An example subtitle from the original recording.",Note="Căn từ chưa chắc chắn"},new SubtitleCue{Start=5,End=6,Text="A second example sentence."}}};Call(f,"SelectSubtitleJob");tabs.SelectedTab=page;f.Refresh();Application.DoEvents();using(var b=new Bitmap(f.Width,f.Height)){using(var g=Graphics.FromImage(b))g.CopyFromScreen(f.Location,Point.Empty,f.Size);b.Save(Path.Combine(Path.GetTempPath(),"v15_148_subtitles.png"));}Check(review.Height>=90,"Review grid has usable height");Console.WriteLine("TOTAL SUBTITLE UI "+count+" passed.");
 }catch(Exception x){Console.WriteLine(x);code=1;}finally{f.Close();}};Application.Run(f);Environment.Exit(code);}
}
